package com.gymmind.nutrition.application; import com.gymmind.audit.application.AuditRecorder; import com.gymmind.audit.domain.*; import com.gymmind.iam.domain.model.RoleCode; import com.gymmind.member.domain.repository.MemberRepository; import com.gymmind.nutrition.domain.model.NutritionPlan; import com.gymmind.nutrition.domain.repository.NutritionPlanRepository; import com.gymmind.shared.error.*; import com.gymmind.shared.security.ActorAccess; import com.gymmind.shared.security.CurrentActor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.Map;
@Service public class DefaultNutritionPlanService implements NutritionPlanService { final NutritionPlanRepository plans; final MemberRepository members; final AuditRecorder audit; public DefaultNutritionPlanService(NutritionPlanRepository p,MemberRepository m,AuditRecorder a){plans=p;members=m;audit=a;} @Transactional public NutritionPlanView create(CurrentActor actor,CreateNutritionPlanCommand c){Long tenantId=ActorAccess.tenantId(actor);if(tenantId==null||(!actor.roles().contains(RoleCode.MEMBER)&&!actor.roles().contains(RoleCode.COACH)&&!ActorAccess.canManageTenant(actor))||!actor.hasPermission("nutrition:write"))throw new BusinessException(ErrorCode.FORBIDDEN);if(c==null||c.tenantId()!=null&&!tenantId.equals(c.tenantId())||c.calories()<0||c.protein()<0||c.carbohydrate()<0||c.fat()<0||c.description()==null||c.description().isBlank())throw new BusinessException(ErrorCode.VALIDATION_FAILED);Long memberId=c.memberId();if(actor.roles().contains(RoleCode.MEMBER)){memberId=members.findByTenantIdAndUserId(tenantId,actor.userId()).map(com.gymmind.member.domain.model.Member::getId).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND));}members.findByTenantIdAndId(tenantId,memberId).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND));NutritionPlan p=plans.save(NutritionPlan.create(tenantId,memberId,c.calories(),c.protein(),c.carbohydrate(),c.fat(),c.description()));audit.record(new AuditEvent("NUTRITION_PLAN_CREATED","NUTRITION_PLAN",p.getId(),AuditResult.SUCCESS,"nutrition-plan-service",Map.of("resourceName",p.getDescription())));return NutritionPlanView.from(p);} }
